{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Konklusionen om vejledende udtalelse, ikke bindende for Udbetaling Danmark og uden krav om undersøgelse er korrekt. Svaret mangler dog det kritiske indhold om studiejob og formulerer indholdet mere generelt. Desuden er der tilføjet påstande uden støtte: at Udbetaling Danmark 'skal inddrage' udtalelsen, og at UDK 'kan fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning'. Det er ikke en fuldstændig korrekt juridisk fremstilling."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element (hvor meget funktionsnedsættelsen påvirker evnen til at arbejde) er dækket med 'evne til at arbejde'. Det andet (om funktionsevnen er så nedsat, at et studiejob ikke kan varetages) mangler helt. Svaret nævner kun erhvervsarbejde/erhvervsevne."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet. Indholdet er upræcist, men svaret er relevant og erstattes ikke af irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til vejledning nr. 10157 (afsnit 5.1.3.3 i kilderne) og bruger nummererede henvisninger og citater, så væsentlige udsagn kan knyttes til en identificerbar kilde."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning nr. 10157 om handicaptillæg findes i det frosne kildemateriale og er en autoritativ og anvendelig kilde. Afsnit 5.1.3.3 er den relevante bestemmelse."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de angivne passager. Henvisningen 3 om 'meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde' bruges som beskrivelse af, hvad udtalelsen skal belyse, men 5.1.3.3 taler om funktionsnedsættelsens påvirkning af evnen til at arbejde og om studiejob. 'Skal inddrage udtalelsen' og 'kan fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning' er knyttet til kilde 2, som kun siger, at udtalelsen 'indgår' i vurderingen og ikke er bindende. Konklusionen 'kun skal inddrage den som et vejledende moment' går ud over kilden."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en regel om, at Udbetaling Danmark 'skal inddrage udtalelsen i sagsbehandlingen', og at UDK 'kan dog fravige udtalelsen, hvis den samlede dokumentation peger i en anden retning'. Begge mangler støtte i materialet. Desuden fremstilles 'erhvervsevne' som udtalelsens genstand i stedet for evnen til at arbejde og studiejob."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den krævede kvalifikation er bevaret: udtalelsen er vejledende, og Udbetaling Danmark er ikke bundet. Svaret nævner også, at udtalelsen bygger på den foreliggende dokumentation uden undersøgelse, og at UDK kan indhente den."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: vejledende udtalelse, ikke bindende, indgår i vurderingen, og UDK afgør. Konklusionen følger af de anførte trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gengiver 'kan' korrekt i forbindelse med anmodning om udtalelse. Det indfører dog en pligtmodalitet, 'skal inddrage udtalelsen', som ikke fremgår af kilden, der blot siger 'indgår'. Den tilføjede 'kan fravige'-formulering er ligeledes en modalitet uden kildestøtte."
    }
  },
  "xhaile_coverage": {
    "A68": {
      "label": "partial",
      "reason": "Svaret dækker, at UDK kan anmode om en vejledende udtalelse om evnen til at arbejde, og at den bygger på dokumentationen uden undersøgelse. Det udelader vurderingen af, om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Det nævner heller ikke, at UDK betaler udgifterne til indhentningen."
    }
  },
  "overall_notes": "Svaret rammer kernen: vejledende, ikke bindende, ingen undersøgelse. Det udelader det kritiske studiejobelement og tilføjer ustøttede regler om pligt til at inddrage og mulighed for at fravige udtalelsen. Kildeangivelsen er identificerbar og gyldig, men flere påstande er ikke understøttet af de citerede passager."
}

